1	package edgefleet
2	
3	import (
4		"bytes"
5		"fmt"
6		"math"
7		"strings"
8		"testing"
9	)
10	
11	// Regression safeguards for the sliding-window event count at the signed
12	// 64-bit limit. Each (key, window) keeps an independent count of the events it
13	// actually received: a normally accepted event -- positive, negative or zero
14	// value alike -- counts once in every window that contains its event time,
15	// independently of that window's sum. An addition that lands the count exactly
16	// on math.MaxInt64 is legal and must close with that exact integer rendered as
17	// a JSON number (no rounding, no sign flip); only the NEXT accepted event,
18	// which would need math.MaxInt64+1 counts, is fatal at its own physical input
19	// line as an *InputError that says "event count overflow" and names the key
20	// and the offending window's left-closed/right-open interval. Overlapping
21	// windows fail independently, and the late-event check runs first, so a
22	// strictly late event is merely skipped (with the existing notice) even when a
23	// still-open window it lands in is already at the count limit. Scope is the
24	// legacy single-watermark RunAggregateSliding entry point.
25	//
26	// The windows under test are seeded straight at the boundary through package
27	// internals: feeding 9223372036854775806 events cannot be done at a finite
28	// offline scale, whereas one seeded state plus a handful of real records read
29	// through the production line collector exercises the exact update loop,
30	// physical line counting (blank lines count), watermark closure and output
31	// formatting.
32	
33	// seedCountWindow prepares one key/window pair already holding count events
34	// and the given sum, marking its end so watermark closure works unchanged.
35	func seedCountWindow(s *aggregateState, key string, start, end, count, sum int64) {
36		s.windows[windowID{start: start, key: key}] = &windowState{end: end, count: count, sum: sum}
37	}
38	
39	// runSlidingState feeds input to an already seeded state through the normal
40	// line collector, so seeding never bypasses physical line counting or any
41	// record check. It returns the captured window output and late-event output.
42	func runSlidingState(s *aggregateState, input string) (string, string, error) {
43		var stdout, stderr bytes.Buffer
44		s.out = &stdout
45		s.lateLog = &stderr
46		err := readAggregateLines(strings.NewReader(input), func(line string, no int) error {
47			if strings.TrimSpace(line) == "" {
48				return nil
49			}
50			return s.processLine(line, no)
51		})
52		return stdout.String(), stderr.String(), err
53	}
54	
55	// newCountState builds a legacy single-watermark sliding state with the given
56	// window length and slide interval and an empty window map.
57	func newCountState(windowMillis, slideMillis int64) *aggregateState {
58		return &aggregateState{
59			windowMillis: windowMillis,
60			slideMillis:  slideMillis,
61			windows:      make(map[windowID]*windowState),
62		}
63	}
64	
65	// A window one event below the limit accepts the next legal event and reaches
66	// math.MaxInt64 exactly: the event must not be rejected early, and the window
67	// closed by a later watermark carries the full integer as a JSON number, with
68	// no rounding and no sign flip. This holds for every value sign -- positive,
69	// negative and zero values are all worth exactly one count. The literal-text
70	// comparison fails if the count were ever rendered through a float64
71	// (9223372036854775807 would print as 9223372036854775808 or, after an integer
72	// wrap, a negative number).
73	func TestAggregateSlidingCountBoundaryReachesMaxInt64Exactly(t *testing.T) {
74		const M = math.MaxInt64
75		const w, sl int64 = 1000, 600
76		// Seed a safe sum of 100 so each value sign is legal to add; the resulting
77		// sum differs by sign but the count must land on MaxInt64 in every case.
78		cases := []struct {
79			name  string
80			value int64
81			sum   int64
82		}{
83			{"positive value", 1, 101},
84			{"negative value", -1, 99},
85			{"zero value", 0, 100},
86		}
87		for _, tc := range cases {
88			t.Run(tc.name, func(t *testing.T) {
89				s := newCountState(w, sl)
90				seedCountWindow(s, "sensor-a", 600, 1600, M-1, 100)
91	
92				input := strings.Join([]string{
93					fmt.Sprintf(`{"type":"event","key":"sensor-a","time":1000,"value":%d}`, tc.value), // M-1 -> M
94					`{"type":"watermark","time":1600}`,
95				}, "\n")
96				stdout, stderr, err := runSlidingState(s, input)
97				if err != nil {
98					t.Fatalf("the event that reaches exactly MaxInt64 must succeed, got: %v", err)
99				}
100				if stderr != "" {
101					t.Fatalf("unexpected stderr: %q", stderr)
102				}
103				want := fmt.Sprintf(`{"key":"sensor-a","start":600,"end":1600,"count":%d,"sum":%d}`+"\n", M, tc.sum)
104				if stdout != want {
105					t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, want)
106				}
107				// Parse it back: the field must survive as the exact positive limit,
108				// not a rounded or negative value.
109				got := decodeAggregateResults(t, stdout)
110				if len(got) != 1 || got[0] != (AggregateResult{Key: "sensor-a", Start: 600, End: 1600, Count: M, Sum: tc.sum}) {
111					t.Fatalf("decoded rows = %v", got)
112				}
113			})
114		}
115	}
116	
117	// Once a window already holds math.MaxInt64 events, the next event that should
118	// otherwise be accepted fails on that line even when its value is zero and
119	// could not overflow the sum. The *InputError reports "event count overflow"
120	// with the physical line number (blank lines count), the key and the window's
121	// [start,end) interval. Records after the failure are not read, open windows
122	// are not replayed, and the result fully written before it stays as is.
123	func TestAggregateSlidingCountOverflowFatalWithZeroValue(t *testing.T) {
124		const M = math.MaxInt64
125		s := newCountState(1000, 600)
126		// A window that closes and is written before the failing record.
127		seedCountWindow(s, "sensor-a", 0, 1000, 1, 7)
128		// The still-open window already holding the maximum number of events; its
129		// sum is deliberately zero so a zero-value event cannot be a sum overflow.
130		seedCountWindow(s, "sensor-a", 600, 1600, M, 0)
131	
132		input := strings.Join([]string{
133			`{"type":"watermark","time":1000}`, // line 1: closes [0,1000)
134			``,                                 // line 2: blank, still counts
135			`{"type":"event","key":"sensor-a","time":1000,"value":0}`,  // line 3: count overflow
136			`{"type":"event","key":"sensor-a","time":1100,"value":-5}`, // line 4: never read
137			`{"type":"watermark","time":1600}`,                         // line 5: never read
138		}, "\n")
139		stdout, _, err := runSlidingState(s, input)
140		if err == nil {
141			t.Fatal("expected event count overflow, got nil")
142		}
143		inputErr, ok := err.(*InputError)
144		if !ok {
145			t.Fatalf("expected *InputError, got %T: %v", err, err)
146		}
147		if inputErr.Line != 3 {
148			t.Errorf("line = %d, want 3 (blank lines must count)", inputErr.Line)
149		}
150		wantReason := `event count overflow for key "sensor-a" window [600,1600)`
151		if inputErr.Reason != wantReason {
152			t.Fatalf("reason = %q, want %q", inputErr.Reason, wantReason)
153		}
154		if got := err.Error(); got != "line 3: "+wantReason {
155			t.Fatalf("error text = %q, want the physical line prefixed to the reason", got)
156		}
157		if got := s.windows[windowID{start: 600, key: "sensor-a"}]; got.count != M || got.sum != 0 {
158			t.Errorf("rejected event must not change the full window, got count=%d sum=%d", got.count, got.sum)
159		}
160		// The pre-failure result stays, and nothing the later watermark would have
161		// closed ([600,1600)) may be appended.
162		want := `{"key":"sensor-a","start":0,"end":1000,"count":1,"sum":7}` + "\n"
163		if stdout != want {
164			t.Fatalf("existing output must be retained with nothing added:\n got: %q\nwant: %q", stdout, want)
165		}
166	}
167	
168	// The count is incremented for every accepted value sign: a negative-valued
169	// event at count M-1 still lands exactly on M (sum moves independently), and
170	// the following zero-valued event is then rejected as a count overflow --
171	// value zero can never masquerade as "no event".
172	func TestAggregateSlidingCountIncrementedForNegativeAndZeroValues(t *testing.T) {
173		const M = math.MaxInt64
174		s := newCountState(1000, 600)
175		seedCountWindow(s, "sensor-a", 600, 1600, M-1, 41)
176	
177		input := strings.Join([]string{
178			`{"type":"event","key":"sensor-a","time":1000,"value":-7}`, // count M-1 -> M, sum 41 -> 34
179			`{"type":"event","key":"sensor-a","time":1100,"value":0}`,  // only [600,1600); count M -> overflow
180			`{"type":"watermark","time":1600}`,                         // never read
181		}, "\n")
182		_, _, err := runSlidingState(s, input)
183		if err == nil {
184			t.Fatal("expected event count overflow, got nil")
185		}
186		inputErr, ok := err.(*InputError)
187		if !ok {
188			t.Fatalf("expected *InputError, got %T: %v", err, err)
189		}
190		if inputErr.Line != 2 {
191			t.Errorf("line = %d, want 2", inputErr.Line)
192		}
193		wantReason := `event count overflow for key "sensor-a" window [600,1600)`
194		if inputErr.Reason != wantReason {
195			t.Fatalf("reason = %q, want %q", inputErr.Reason, wantReason)
196		}
197		got := s.windows[windowID{start: 600, key: "sensor-a"}]
198		if got.count != M {
199			t.Errorf("the negative-value event must have counted exactly once: count = %d, want %d", got.count, M)
200		}
201		if got.sum != 34 {
202			t.Errorf("sum = %d, want 34 (41-7); the rejected zero-value event must not touch it", got.sum)
203		}
204	}
205	
206	// Counts of overlapping windows are independent. The same event lands in a
207	// window that can still take it and windows already at the limit; the failure
208	// names the window that actually goes over and must not blame the safe one.
209	// Containing windows are visited in ascending start order, so when more than
210	// one containing window is already full the earliest such start is named; the
211	// full windows reached only after that point stay exactly at the limit.
212	func TestAggregateSlidingCountOverflowNamesOnlyTheFullWindow(t *testing.T) {
213		const M = math.MaxInt64
214		s := newCountState(1000, 300)
215		// The event at 1000 (window 1000, slide 300) belongs to [300,1300),
216		// [600,1600) and [900,1900). The first can still take events; the other two
217		// are already at the limit.
218		seedCountWindow(s, "k", 300, 1300, 5, 0)
219		seedCountWindow(s, "k", 600, 1600, M, 0)
220		seedCountWindow(s, "k", 900, 1900, M, 0)
221	
222		input := strings.Join([]string{
223			`{"type":"event","key":"k","time":1000,"value":0}`, // line 1: fails at [600,1600)
224			`{"type":"event","key":"k","time":1001,"value":0}`, // line 2: never read
225			`{"type":"watermark","time":1900}`,                 // line 3: never read
226		}, "\n")
227		stdout, _, err := runSlidingState(s, input)
228		if err == nil {
229			t.Fatal("expected event count overflow, got nil")
230		}
231		inputErr, ok := err.(*InputError)
232		if !ok {
233			t.Fatalf("expected *InputError, got %T: %v", err, err)
234		}
235		if inputErr.Line != 1 {
236			t.Errorf("line = %d, want 1", inputErr.Line)
237		}
238		wantReason := `event count overflow for key "k" window [600,1600)`
239		if inputErr.Reason != wantReason {
240			t.Fatalf("reason = %q, want %q", inputErr.Reason, wantReason)
241		}
242		// The safe earlier window is not the offender, nor is the later full window.
243		if strings.Contains(inputErr.Reason, "[300,1300)") {
244			t.Errorf("reason must not blame the safe window [300,1300): %q", inputErr.Reason)
245		}
246		if strings.Contains(inputErr.Reason, "[900,1900)") {
247			t.Errorf("reason must name the earliest full window, not [900,1900): %q", inputErr.Reason)
248		}
249		// Windows visited at or after the failure stay untouched at the limit.
250		if full := s.windows[windowID{start: 600, key: "k"}]; full.count != M || full.sum != 0 {
251			t.Errorf("[600,1600) must stay at the limit unchanged, got count=%d sum=%d", full.count, full.sum)
252		}
253		if later := s.windows[windowID{start: 900, key: "k"}]; later.count != M || later.sum != 0 {
254			t.Errorf("[900,1900) must never be reached, got count=%d sum=%d", later.count, later.sum)
255		}
256		// The run aborts before line 3's watermark: every involved window is still
257		// open, so none of them -- including the safe one -- can be emitted.
258		if stdout != "" {
259			t.Fatalf("no open window may be output after the failure, got %q", stdout)
260		}
261	}
262	
263	// A strictly late event is skipped before any window update: even when a
264	// still-open window it falls into already holds math.MaxInt64 events, it
265	// produces only the existing late-event notice -- never a count overflow --
266	// and changes neither count nor sum. An event exactly at the watermark is not
267	// late and is processed normally, so it is the one that overflows the count,
268	// even with value zero.
269	func TestAggregateSlidingCountOverflowLateEventSkippedFirst(t *testing.T) {
270		const M = math.MaxInt64
271		s := newCountState(1000, 600)
272		wm := int64(1000)
273		s.watermark = &wm
274		// The still-open overlapping [600,1600) already at the count limit.
275		seedCountWindow(s, "sensor-a", 600, 1600, M, 9)
276	
277		input := strings.Join([]string{
278			`{"type":"event","key":"sensor-a","time":999,"value":0}`,  // line 1: strictly late, skipped
279			`{"type":"event","key":"sensor-a","time":1000,"value":0}`, // line 2: equals watermark -> count overflow
280			`{"type":"watermark","time":1600}`,                        // line 3: never read
281		}, "\n")
282		_, stderr, err := runSlidingState(s, input)
283		if err == nil {
284			t.Fatal("expected event count overflow at the watermark-equal event, got nil")
285		}
286		inputErr, ok := err.(*InputError)
287		if !ok {
288			t.Fatalf("expected *InputError, got %T: %v", err, err)
289		}
290		if inputErr.Line != 2 {
