1	package main
2	
3	import (
4		"strings"
5		"testing"
6	)
7	
8	// Command-line regression coverage for how "aggregate" treats --slide-ms at
9	// the command entry point. The package tests cover the sliding window math
10	// directly; these tests drive the real main() in a child process (see
11	// main_test.go for the harness) so they guard what the flag actually decides:
12	//
13	//   - omitting --slide-ms is fixed-window mode, byte for byte identical to
14	//     passing --slide-ms equal to --window-ms;
15	//   - an explicit positive interval below the window length reaches the
16	//     aggregator and each event counts in full in every window containing it
17	//     (the value is never split, and this is not just relabeled start/end);
18	//   - a non-dividing interval is legal and produces a distinct result grid;
19	//   - an explicitly given zero is rejected (exit 2) even though an omitted
20	//     flag defaults to fixed windows, along with negative, oversized and
21	//     out-of-int64 values, all before the first input record is read.
22	
23	// Omitting --slide-ms and setting it explicitly to the window length must run
24	// the same fixed windows through the command entry point. With two keys and
25	// out-of-order records this asserts start/end, count and sum per line, the
26	// end-then-key ordering, and the successful exit with an empty standard error
27	// for both invocations; the two runs' raw output is compared as well so no
28	// whitespace or field difference can slip in between the two ways of asking.
29	func TestAggregateCLISlideOmittedEqualsExplicitWindowLength(t *testing.T) {
30		input := strings.Join([]string{
31			`{"type":"event","key":"b","time":800,"value":-2}`,
32			`{"type":"event","key":"a","time":1500,"value":7}`,
33			`{"type":"event","key":"a","time":1200,"value":5}`, // out of order, same fixed window
34			`{"type":"event","key":"b","time":0,"value":4}`,
35			`{"type":"watermark","time":2000}`,
36		}, "\n") + "\n"
37	
38		type run struct {
39			name   string
40			args   []string
41			stdout string
42		}
43		runs := []run{
44			{name: "slide omitted", args: []string{"--window-ms", "1000"}},
45			{name: "slide equals window", args: []string{"--window-ms", "1000", "--slide-ms", "1000"}},
46		}
47		expected := []windowLine{
48			{Key: "b", Start: 0, End: 1000, Count: 2, Sum: 2},     // 4 and -2
49			{Key: "a", Start: 1000, End: 2000, Count: 2, Sum: 12}, // 5 and 7
50		}
51	
52		for i := range runs {
53			code, stdout, stderr := runAggregateCLI(t, input, runs[i].args...)
54			if code != 0 {
55				t.Fatalf("%s: exit code = %d, want 0; stderr: %s", runs[i].name, code, stderr)
56			}
57			if stderr != "" {
58				t.Fatalf("%s: stderr = %q, want empty", runs[i].name, stderr)
59			}
60			assertWindowLines(t, stdout, expected)
61			runs[i].stdout = stdout
62		}
63		if runs[0].stdout != runs[1].stdout {
64			t.Fatalf("omitted slide output %q != explicit --slide-ms 1000 output %q", runs[0].stdout, runs[1].stdout)
65		}
66	}
67	
68	// A smaller explicit --slide-ms must do more than rename window boundaries:
69	// an event counts once, with its full value, in EVERY window that contains
70	// its time. Length 1000 with slide 600 gives [0,1000), [600,1600),
71	// [1200,2200); the boundary events prove the left-closed/right-open rule
72	// survives the command entry: time 0 enters the first window, time 1000 is
73	// excluded from it (an event exactly at a start belongs to that window, an
74	// event exactly at an end does not), and time 1600 belongs to neither of the
75	// first two. The watermark 1600 closes exactly end <= 1600, ordered by end
76	// then key; [1200,2200) stays open at end of input and must never appear.
77	func TestAggregateCLISlideExplicitCountsEventInFullInEveryContainingWindow(t *testing.T) {
78		input := strings.Join([]string{
79			`{"type":"event","key":"k","time":0,"value":5}`,    // [0,1000) only
80			`{"type":"event","key":"k","time":700,"value":-3}`, // [0,1000) and [600,1600)
81			`{"type":"event","key":"k","time":1000,"value":9}`, // [600,1600) only, not [0,1000)
82			`{"type":"event","key":"k","time":1600,"value":2}`, // [1200,2200) only; excluded at [600,1600)'s end
83			`{"type":"watermark","time":1000}`,
84			`{"type":"watermark","time":1600}`,
85		}, "\n") + "\n"
86	
87		code, stdout, stderr := runAggregateCLI(t, input, "--window-ms", "1000", "--slide-ms", "600")
88		if code != 0 {
89			t.Fatalf("exit code = %d, want 0; stderr: %s", code, stderr)
90		}
91		if stderr != "" {
92			t.Fatalf("stderr = %q, want empty", stderr)
93		}
94		assertWindowLines(t, stdout, []windowLine{
95			{Key: "k", Start: 0, End: 1000, Count: 2, Sum: 2},   // 5 + (-3): full values, time-1000 excluded
96			{Key: "k", Start: 600, End: 1600, Count: 2, Sum: 6}, // (-3) + 9: time-1600 excluded
97		})
98	}
99	
100	// Multiple keys inside one overlapping window are accumulated separately and
101	// emitted in the existing end-ascending, key (UTF-8 byte) order. A multi-key,
102	// multi-window batch closed by one watermark guards that the ordering rule is
103	// unchanged when --slide-ms is supplied.
104	func TestAggregateCLISlideExplicitClosureOrderByEndThenKey(t *testing.T) {
105		input := strings.Join([]string{
106			`{"type":"event","key":"中","time":700,"value":1}`,
107			`{"type":"event","key":"A","time":700,"value":1}`,
108			`{"type":"event","key":"é","time":100,"value":1}`,
109			`{"type":"event","key":"A","time":1100,"value":1}`,
110			`{"type":"watermark","time":1600}`,
111		}, "\n") + "\n"
112	
113		code, stdout, stderr := runAggregateCLI(t, input, "--window-ms", "1000", "--slide-ms", "600")
114		if code != 0 {
115			t.Fatalf("exit code = %d, want 0; stderr: %s", code, stderr)
116		}
117		if stderr != "" {
118			t.Fatalf("stderr = %q, want empty", stderr)
119		}
120		assertWindowLines(t, stdout, []windowLine{
121			{Key: "A", Start: 0, End: 1000, Count: 1, Sum: 1},
122			{Key: "é", Start: 0, End: 1000, Count: 1, Sum: 1},
123			{Key: "中", Start: 0, End: 1000, Count: 1, Sum: 1},
124			{Key: "A", Start: 600, End: 1600, Count: 2, Sum: 2}, // t=700 and t=1100
125			{Key: "中", Start: 600, End: 1600, Count: 1, Sum: 1}, // t=700
126		})
127	}
128	
129	// An interval that does not divide the window length is legal, and the
130	// observed output must distinguish it from both fixed windows and a dividing
131	// interval. Length 1000 with slide 300 starts windows at 0, 300, 600, ...;
132	// the event at 700 lands in [0,1000), [300,1300) and [600,1600) in full,
133	// while an equal fixed/1000 run would show one window and an equal dividing
134	// 500 run would show a different two-window grid. The empty [900,1900) is not
135	// emitted and [1200,2200)-and-later stay open past watermark 2000.
136	func TestAggregateCLISlideNonDividingIntervalIsDistinctGrid(t *testing.T) {
137		input := strings.Join([]string{
138			`{"type":"event","key":"k","time":0,"value":1}`,
139			`{"type":"event","key":"k","time":700,"value":1}`,
140			`{"type":"watermark","time":2000}`,
141		}, "\n") + "\n"
