169		// Same input with a dividing interval (500): windows at 0, 500, 1000, so
170		// t=700 covers [0,1000) and [500,1500) only -- different starts/ends from
171		// the 300 grid.
172		divCode, divOut, divErr := runAggregateCLI(t, input, "--window-ms", "1000", "--slide-ms", "500")
