185	// Windows that have not closed stay silent through end of input: the
186	// watermark closes only end <= watermark windows and the process exits 0
187	// without flushing the open overlap window or printing anything on stderr.
188	func TestAggregateCLISlideWatermarkClosesOnlyEndAtOrBelowIt(t *testing.T) {
189		input := strings.Join([]string{
190			`{"type":"event","key":"k","time":700,"value":5}`,
191			`{"type":"watermark","time":999}`, // [0,1000) end 1000 > 999: nothing
