208	// Explicit zero must be rejected even though omitting the flag defaults to
209	// fixed windows: the two spellings are observably different at the entry
210	// point. Zero exits 2 as an argument error with the flag name and the reason
211	// on stderr and nothing on stdout; omission exits 0 with normal results.
212	func TestAggregateCLISlideZeroRejectedWhileOmissionAccepted(t *testing.T) {
213		input := strings.Join([]string{
214			`{"type":"event","key":"k","time":100,"value":2}`,
