243	
244	// Every invalid --slide-ms spelling fails as an argument error: exit code 2,
245	// the offending flag and reason on standard error, no window result on
246	// standard output, and the check happens before input is read. The last point
247	// is pinned two ways: input that would immediately close a window must still
248	// produce nothing, and input whose FIRST record is malformed must surface the
249	// parameter problem -- never a "line 1" record error and never a silent
250	// fallback to the default fixed interval.
251	func TestAggregateCLISlideInvalidValuesExit2BeforeInput(t *testing.T) {
252		invalid := []struct {
253			name     string
254			value    string
255			wantMsgs []string // substrings that must all appear on stderr
256		}{
257			{"zero", "0", []string{"--slide-ms", "positive"}},
258			{"negative", "-600", []string{"--slide-ms", "positive"}},
259			{"min int64", "-9223372036854775808", []string{"--slide-ms", "positive"}},
260			{"larger than window", "1001", []string{"--slide-ms", "must not exceed", "--window-ms"}},
261			{"equal plus one of larger window", "2001", []string{"--slide-ms", "must not exceed"}},
262			{"above max int64", "9223372036854775808", []string{"slide-ms"}},
263			{"far above max int64", "99999999999999999999999999", []string{"slide-ms"}},
264			{"not an integer", "six-hundred", []string{"slide-ms"}},
265			{"not a whole number", "6.0", []string{"slide-ms"}},
