268		// Would close [0,1000) as soon as parsing succeeded.
269		closingInput := strings.Join([]string{
270			`{"type":"event","key":"k","time":100,"value":2}`,
271			`{"type":"watermark","time":1000}`,
272		}, "\n") + "\n"
273		// First physical line is not a record at all: a record error would say
274		// "line 1"; an argument error must win and mention no line number.
275		malformedFirstInput := `{"type":"event",broken` + "\n"
276	
277		for _, iv := range invalid {
278			window := "1000"
279			if iv.name == "equal plus one of larger window" {
280				window = "2000"
281			}
282			for _, in := range []struct {
283				name, text string
284			}{
285				{"closing input", closingInput},
286				{"malformed first record", malformedFirstInput},
287				{"empty input", ""},
288			} {
289				t.Run(iv.name+"/"+in.name, func(t *testing.T) {
