291					if code != 2 {
292						t.Fatalf("exit code = %d, want 2; stderr: %s", code, stderr)
293					}
294					if stdout != "" {
295						t.Fatalf("stdout = %q, want empty: invalid --slide-ms must fail before any window is produced", stdout)
296					}
297					for _, want := range iv.wantMsgs {
298						if !strings.Contains(stderr, want) {
299							t.Fatalf("stderr = %q, want it to mention %q", stderr, want)
300						}
301					}
302					if strings.Contains(stderr, "line 1") || strings.Contains(stderr, "invalid JSON") {
303						t.Fatalf("bad --slide-ms must be reported as an argument error, not a record problem: stderr = %q", stderr)
304					}
305				})
306			}
307		}
308	}
309	
310	// The existing --window-ms requirement is unchanged by adding --slide-ms
311	// coverage: with slide given but window omitted the run still exits 2 naming
312	// --window-ms, before input is read; and a non-positive window exits 2 even
313	// when a valid slide accompanies it. No window results may appear.
314	func TestAggregateCLISlideKeepsWindowRequired(t *testing.T) {
315		input := `{"type":"watermark","time":1000}` + "\n"
316	
