323			{"window omitted", nil, "--window-ms"},
324			{"window zero despite valid slide", []string{"--window-ms", "0", "--slide-ms", "600"}, "--window-ms"},
325			{"window negative despite valid slide", []string{"--window-ms", "-1000", "--slide-ms", "600"}, "--window-ms"},
326		}
327		for _, tc := range cases {
328			t.Run(tc.name, func(t *testing.T) {
329				code, stdout, stderr := runAggregateCLI(t, input, tc.args...)
330				if code != 2 {
331					t.Fatalf("exit code = %d, want 2; stderr: %s", code, stderr)
332				}
333				if stdout != "" {
334					t.Fatalf("stdout = %q, want empty", stdout)
335				}
336				if !strings.Contains(stderr, tc.wantText) {
337					t.Fatalf("stderr = %q, want it to mention %q", stderr, tc.wantText)
338				}
339			})
340		}
341	}
