// Sliding closure frees exactly the windows that closed: closing the earlier
// of two overlapping windows releases one of the two slots while the later
// stays open, so a brand-new single-window key fits but a key needing two
// windows still does not.
func TestMaxOpenWindowsSlidingClosureFreesOnlyClosedWindows(t *testing.T) {
	// a@700 occupies starts 0 and 600; watermark 1000 closes only start 0
	// ([0,1000) end == 1000), leaving [600,1600) open: occupancy goes 2 -> 1.
	base := []string{
		`{"type":"event","key":"a","time":700,"value":1}`,
		`{"type":"watermark","time":1000}`,
	}
	oneFits := append(append([]string{}, base...),
		`{"type":"event","key":"b","time":1100,"value":2}`, // belongs only to [600,1600)? see below
	)
	// time 1100 with slide 600 belongs to starts 600 and 1200: start 600
	// exists for a but not for b, so b needs TWO new pairs -> 1+2 > 2.
	_, _, err := runMaxOpen(t, strings.Join(oneFits, "\n")+"\n", 1000, 600, 0, 2)
	assertInputError(t, err, 3, `key "b"`, "1 window(s) currently open", "needs 2 new window(s)", "limit 2")

	// A fixed-window-like single new pair at time 1600 (start 1200 only relative
	// to b) reuses nothing for b, so instead reuse the SAME open pair for a:
	// another a event at 1100 folds into the already-open (a,600) and the
	// freshly created (a,1200): that needs one slot, 1+1 == 2 -> accepted.
	reuse := append(append([]string{}, base...),
		`{"type":"event","key":"a","time":1100,"value":2}`,
		`{"type":"watermark","time":2200}`,
	)
	stdout, stderr, err := runMaxOpen(t, strings.Join(reuse, "\n")+"\n", 1000, 600, 0, 2)
	if err != nil {
		t.Fatalf("one freed slot accepting one new pair must succeed: %v", err)
	}
	if stderr != "" {
		t.Fatalf("unexpected stderr: %q", stderr)
	}
	want := strings.Join([]string{
		`{"key":"a","start":0,"end":1000,"count":1,"sum":1}`,
		`{"key":"a","start":600,"end":1600,"count":2,"sum":3}`,
		`{"key":"a","start":1200,"end":2200,"count":1,"sum":2}`,
		``,
	}, "\n")
	if stdout != want {
		t.Fatalf("stdout = %q, want %q", stdout, want)
	}
}

