		"line 3",
		`key "c"`,
		"2 window(s) currently open",
		"needs 1 new window(s)",
		"limit 2",
	} {
		if !strings.Contains(stderr, want) {
			t.Fatalf("stderr = %q, want it to mention %q", stderr, want)
		}
	}
